import type { StorefrontProduct } from "@cartforge/types";

/** JSON for a <script> tag: escapes "<" so data can never close the tag. */
export function jsonLd(data: unknown): string {
  return JSON.stringify(data).replace(/</g, "\\u003c");
}

const decimal = (minor: number, currency: string) => {
  const digits =
    new Intl.NumberFormat("en", { style: "currency", currency }).resolvedOptions()
      .maximumFractionDigits ?? 2;
  return (minor / 10 ** digits).toFixed(digits);
};

/** schema.org Product (PRD §8.4 H: structured data generated by storefront rules). */
export function productJsonLd(p: StorefrontProduct, url: string) {
  const priced = p.variants.filter((v) => v.price_minor !== null);
  const availability = (ok: boolean) =>
    ok ? "https://schema.org/InStock" : "https://schema.org/OutOfStock";
  const offers =
    p.price_min_minor === null
      ? undefined
      : priced.length > 1 && p.price_min_minor !== p.price_max_minor
        ? {
            "@type": "AggregateOffer",
            priceCurrency: p.currency,
            lowPrice: decimal(p.price_min_minor, p.currency),
            highPrice: decimal(p.price_max_minor ?? p.price_min_minor, p.currency),
            offerCount: priced.length,
            availability: availability(p.available),
          }
        : {
            "@type": "Offer",
            url,
            priceCurrency: p.currency,
            price: decimal(p.price_min_minor, p.currency),
            availability: availability(p.available),
          };
  return {
    "@context": "https://schema.org",
    "@type": "Product",
    name: p.title,
    description: p.seo.description || undefined,
    url,
    image: p.images.map((i) => i.large_url ?? i.url).slice(0, 10),
    brand: p.vendor ? { "@type": "Brand", name: p.vendor } : undefined,
    ...(offers ? { offers } : {}),
  };
}

export function breadcrumbJsonLd(items: { name: string; url: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((it, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: it.name,
      item: it.url,
    })),
  };
}
